// b-studio가 만든 파일입니다. 고쳐도 다음에 터미널을 열 때 다시 쓰입니다.
import { spawn } from 'node:child_process';
import { readFileSync } from 'node:fs';
import http from 'node:http';

const TIMEOUT_SECONDS = {"session-start":15,"prompt":60,"pre-tool":1800,"stop":3600,"session-end":10,"stop-failure":120,"notification":15,"activity":5,"statusline":3,"ping":8};
const event = process.argv[2] ?? '';

function finish(output) {
  if (output !== undefined) process.stdout.write(JSON.stringify(output));
  process.exit(0);
}

// 읽기만 요청인가. 서버와 같은 규칙이다(Rust 코어의 classify, 같은 꼴의 isReadOnlyPrompt) — 붙여 넣은 요청의 감싸개를 더 벗길 것이 없을 때까지 벗기며 단계마다 본다
function readOnlyPrompt() {
  try {
    const prompt = JSON.parse(body.toString('utf8')).prompt;
    if (typeof prompt !== 'string') return false;
    let current = prompt;
    for (let step = 0; step < 64; step += 1) {
      const next = current.replace(new RegExp("<pasted_content(?:\\s+id=\"[^\"]*\")?>\\r?\\n?", 'g'), '').replace(new RegExp("\\r?\\n?</pasted_content(?:\\s+id=\"[^\"]*\")?>", 'g'), '');
      if (next.normalize('NFC').replace(new RegExp("^[\\s\\u200b-\\u200f\\u2060\\ufeff\\u202a-\\u202e\\u2066-\\u2069]+"), '').startsWith("[읽기만]")) return true;
      if (next === current) return false;
      current = next;
    }
    return true;
  } catch {
    return false;
  }
}

function unreachable(why) {
  if (event === 'ping') process.exit(1);
  // 읽기만 요청은 등록하지 못하면 보내지 않는다. 그냥 보내면 서버는 이 요청이 읽기만인 줄 모르고, 뒤따르는 쓰기 도구를 보통 요청의 것으로 받아 준다
  if (event === 'prompt' && readOnlyPrompt()) finish({ decision: 'block', reason: '[b-studio] 읽기만 요청을 등록하지 못해 보내지 않았습니다(' + why + '). 다시 보내 주세요.' });
  if (event === 'prompt') finish({ systemMessage: '[b-studio] 관문에 닿지 못했습니다(' + why + '). 이 요청의 변경은 검증되지 않고 체크포인트도 생기지 않습니다.' });
  if (event === 'pre-tool') finish({ hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: '[b-studio] 관문에 닿지 못해(' + why + ') 파일을 바꿀 수 있는 도구를 막았습니다. 변경 전 기준을 잡을 수 없습니다.' } });
  finish();
}

