// 입력을 먼저 읽는다. 관문에 닿지 못했을 때도 요청 글을 보고 판단할 것이 있다(읽기만 요청)
const chunks = [];
for await (const chunk of process.stdin) chunks.push(chunk);
const body = Buffer.concat(chunks);

let base;
let token;
try {
  const address = JSON.parse(readFileSync(new URL('./b-studio-gateway.json', import.meta.url), 'utf8'));
  base = address.url;
  token = address.token;
} catch {
  // 아래에서 주소가 없는 것으로 다룬다
}
// 상태 줄(#920): 입력을 관문에 알리고(닿지 못해도 상관없다) 옆 파일에 적힌 사용자의 원래 상태 줄을 같은 입력으로 불러 그 출력을 낸다
